// Helper to convert SVG string or custom image URL into an Image element / Data URI for Three.js textures
window.getArtworkDataUri = function(keyOrDataUrl) {
  if (!keyOrDataUrl) return '';
  if (keyOrDataUrl.startsWith('data:') || keyOrDataUrl.startsWith('http') || keyOrDataUrl.startsWith('blob:')) {
    return keyOrDataUrl;
  }
  const svg = window.GALAXY_ARTWORK[keyOrDataUrl] || window.GALAXY_ARTWORK.spideyKitty;
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg.trim());
};


